<template><div>
    <workspace-heading section="运行态势 / MONITORING" title="监控中心" description="查看主机采集状态、资源指标及告警规则。"/>
<a-alert type="info" show-icon message="Prometheus 每 60 秒主动采集 Node Exporter，平台查询指标并同步告警。采集端点失联不等于服务器关机；通知暂不启用。"/>
<a-row :gutter="16" style="margin:16px 0"><a-col :xs="12" :lg="6" class="summary-card" v-for="card in cards" :key="card.label"><a-card size="small"><a-statistic :title="card.label" :value="card.value"/></a-card></a-col></a-row>
<a-alert v-if="error" type="warning" :message="error"/><a-alert v-if="health.monitor_error||health.config_error" type="warning" :message="health.config_error||health.monitor_error"/>
<a-tabs><a-tab-pane key="hosts" tab="主机监控"><a-space wrap style="margin:12px 0"><a-input-search v-model:value="search" placeholder="搜索名称 / 地址 / 业务"/><a-select v-model:value="stateFilter" allow-clear placeholder="全部采集状态" style="width:160px" :options="options(targetStates)"/><a-button :loading="loading" @click="load">刷新</a-button><span>每 30 秒刷新页面，历史指标保留 7 天</span></a-space>
<a-table :data-source="filtered" :columns="columns" row-key="id" :pagination="{pageSize:20}" :scroll="{x:1400}"><template #bodyCell="{column,record}"><template v-if="column.key==='name'"><a @click="router.push({name:'HostWorkbench',params:{id:record.id}})">{{record.name}}</a><div>{{record.ip_addr}}</div></template><template v-if="column.key==='state'"><a-tag :color="stateColor[record.state]">{{targetStates[record.state]}}</a-tag></template><template v-if="['cpu','memory','disk','inode'].includes(column.key)"><span :style="{color:(record.metrics[column.key]??0)>=85?'#cf1322':''}">{{number(record.metrics[column.key])}}<template v-if="record.metrics[column.key]!=null">%</template></span></template><template v-if="column.key==='load'">{{number(record.metrics.load)}}</template><template v-if="column.key==='network'">↓ {{rate(record.metrics.rx)}}<br/>↑ {{rate(record.metrics.tx)}}</template><template v-if="column.key==='sample'">{{record.metrics.sample_time?time(record.metrics.sample_time*1000):'—'}}</template><template v-if="column.key==='action'"><a-space><a-button @click="selected=record" :disabled="!record.target?.enabled">趋势</a-button><a-button v-if="admin" @click="configure(record)">接入配置</a-button></a-space></template></template></a-table></a-tab-pane>
<a-tab-pane key="services" tab="服务健康"><a-alert type="info" message="HTTP 探测独立于 Node Exporter，按实际服务响应判断是否恢复。"/><a-button style="margin:12px 0" @click="router.push({name:'Diagnostics'})">查看 HTTP 探测与策略</a-button></a-tab-pane>
<a-tab-pane key="rules" tab="告警规则"><a-alert type="info" message="规则由 Prometheus 计算，适用于所有已启用的采集目标。持续时间用于防抖；恢复保持可抑制短暂恢复。此处只产生站内告警记录，不发送通知。"/><a-button v-if="admin" style="margin:12px 0" @click="editRule()">新建规则</a-button><a-table :data-source="rules" :columns="ruleColumns" row-key="id"><template #bodyCell="{column,record}"><template v-if="column.key==='condition'">{{metricNames[record.metric]}} {{record.metric==='up'?'失联':'> '+record.threshold+(['load','collector_failures'].includes(record.metric)?'':'%')}}<br/>持续 {{record.duration}} 秒 / 恢复保持 {{record.recovery_seconds}} 秒</template><template v-if="column.key==='severity'"><a-tag :color="severityColor[record.severity]">{{severityNames[record.severity]}}</a-tag></template><template v-if="column.key==='enabled'"><a-tag :color="record.enabled?'green':'default'">{{record.enabled?'启用':'停用'}}</a-tag></template><template v-if="column.key==='action'"><a-button v-if="admin" @click="editRule(record)">编辑</a-button></template></template></a-table></a-tab-pane>
<a-tab-pane key="health" tab="平台健康"><a-descriptions bordered :column="2"><a-descriptions-item label="任务执行器">{{health.worker_active?'在线':'离线'}}</a-descriptions-item><a-descriptions-item label="队列等待">{{health.queue_pending}} 个</a-descriptions-item><a-descriptions-item label="最早排队时间">{{time(health.oldest_pending_at)}}</a-descriptions-item><a-descriptions-item label="监控同步器">{{health.monitor_active?'在线':'未运行 / 心跳过期'}}</a-descriptions-item><a-descriptions-item label="最近同步成功">{{time(health.monitor_last_success)}}</a-descriptions-item><a-descriptions-item label="通知">本轮不启用</a-descriptions-item><a-descriptions-item label="同步错误">{{health.monitor_error||'无'}}</a-descriptions-item><a-descriptions-item label="配置应用错误">{{health.config_error||'无'}}</a-descriptions-item></a-descriptions></a-tab-pane></a-tabs>
<a-modal :open="!!selected" :title="(selected?.name||'')+' · 指标趋势'" width="1000px" @ok="selected=null" @cancel="selected=null" destroy-on-close><MetricChart v-if="selected" :host-id="selected.id"/></a-modal>
<a-modal v-model:open="configOpen" title="接入 Prometheus 采集" @ok="saveTarget"><a-alert type="warning" message="仅配置采集目标，不会安装软件或开放服务器端口。使用受控内网地址，测试隧道可填 127.0.0.1:19100；勿将无认证采集接口暴露公网。"/><a-form layout="vertical"><a-form-item label="采集地址（主机:端口）"><a-input v-model:value="targetForm.endpoint"/></a-form-item><a-form-item label="启用采集"><a-switch v-model:checked="targetForm.enabled"/></a-form-item></a-form></a-modal>
<a-modal v-model:open="ruleOpen" title="告警规则" @ok="saveRule"><a-form layout="vertical"><a-form-item label="名称"><a-input v-model:value="ruleForm.name"/></a-form-item><a-form-item label="指标"><a-select v-model:value="ruleForm.metric" :options="options(metricNames)"/></a-form-item><a-form-item v-if="ruleForm.metric!=='up'" label="超过阈值"><a-input-number v-model:value="ruleForm.threshold" :min="0" :max="['load','collector_failures'].includes(ruleForm.metric)?10000:100"/></a-form-item><a-form-item label="持续异常秒数"><a-input-number v-model:value="ruleForm.duration" :min="0" :max="86400"/></a-form-item><a-form-item label="恢复保持秒数"><a-input-number v-model:value="ruleForm.recovery_seconds" :min="0" :max="3600"/></a-form-item><a-form-item label="级别"><a-select v-model:value="ruleForm.severity" :options="[{value:'critical',label:'严重'},{value:'warning',label:'警告'},{value:'info',label:'提示'}]"/></a-form-item><a-form-item label="启用"><a-switch v-model:checked="ruleForm.enabled"/></a-form-item></a-form></a-modal>
</div></template>
<script setup>
import WorkspaceHeading from '@/components/WorkspaceHeading.vue'
import {ref,computed,onMounted,onBeforeUnmount} from 'vue'
import {useStore} from 'vuex'
import {useRouter} from 'vue-router'
import {message} from 'ant-design-vue'
import api from '@/api'
import {time,options} from '@/utils/ops'
import {severityColor,severityNames,stateColor} from '@/utils/signals'
import MetricChart from '@/components/MetricChart.vue'
const store=useStore(),router=useRouter(),admin=computed(()=>store.getters.userInfo?.is_superuser)
const rows=ref([]),rules=ref([]),health=ref({}),error=ref(''),loading=ref(false),search=ref(''),stateFilter=ref(),selected=ref(null),configOpen=ref(false),targetForm=ref({}),ruleOpen=ref(false),ruleForm=ref({})
const targetStates={up:'采集正常',partial:'部分采集器失败',down:'采集端点失联',unknown:'状态未知',stale:'数据过期',disabled:'已停用',not_configured:'未接入'}
const metricNames={up:'采集端点',cpu:'CPU 使用率',memory:'内存使用率',disk:'文件系统使用率',inode:'inode 使用率',load:'一分钟负载',collector_failures:'失败采集器数'}
const filtered=computed(()=>rows.value.filter(r=>(!stateFilter.value||r.state===stateFilter.value)&&`${r.name} ${r.ip_addr} ${r.business}`.includes(search.value)))
const cards=computed(()=>[{label:'授权主机',value:rows.value.length},{label:'采集正常',value:rows.value.filter(r=>r.state==='up').length},{label:'失联 / 未知 / 过期',value:rows.value.filter(r=>['down','unknown','stale','partial'].includes(r.state)).length},{label:'未接入 / 停用',value:rows.value.filter(r=>['not_configured','disabled'].includes(r.state)).length}])
const columns=[{title:'主机',key:'name',width:190},{title:'采集状态',key:'state',width:140},{title:'CPU',key:'cpu'},{title:'内存',key:'memory'},{title:'磁盘',key:'disk'},{title:'inode',key:'inode'},{title:'负载',key:'load'},{title:'网络速率',key:'network',width:140},{title:'最近采集',key:'sample',width:180},{title:'操作',key:'action',width:210}]
const ruleColumns=[{title:'规则',dataIndex:'name'},{title:'条件',key:'condition'},{title:'级别',key:'severity'},{title:'状态',key:'enabled'},{title:'操作',key:'action'}]
const number=v=>v==null?'—':Number(v).toFixed(1)
const rate=v=>v==null?'—':v>1048576?(v/1048576).toFixed(1)+' MiB/s':(v/1024).toFixed(1)+' KiB/s'
let timer
async function load(){if(loading.value)return;loading.value=true;try{const [a,b,c]=await Promise.all([api.get('/monitoring/overview'),api.get('/monitoring/rules'),api.get('/monitoring/health')]);rows.value=a.data.rows;error.value=a.data.error;rules.value=b.data;health.value=c.data}finally{loading.value=false}}
function configure(row){targetForm.value={host_id:row.id,endpoint:row.target?.endpoint||`${row.ip_addr}:9100`,enabled:row.target?.enabled??true};configOpen.value=true}
async function saveTarget(){await api.patch(`/monitoring/targets/${targetForm.value.host_id}`,targetForm.value);configOpen.value=false;message.success('已保存，等待同步器应用');load()}
function editRule(row){ruleForm.value=row?{...row}:{name:'',metric:'cpu',threshold:90,duration:300,recovery_seconds:120,severity:'warning',enabled:true};ruleOpen.value=true}
async function saveRule(){const f=ruleForm.value;if(f.id)await api.patch(`/monitoring/rules/${f.id}`,f);else await api.post('/monitoring/rules',f);ruleOpen.value=false;message.success('已保存，等待同步器应用');load()}
onMounted(()=>{load();timer=setInterval(()=>{if(!document.hidden)load()},30000)})
onBeforeUnmount(()=>clearInterval(timer))
</script>

<style scoped>.summary-card{margin-bottom:8px}</style>
